def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    alpha = list(alphabet)
    k = len(alpha)
    pos = {c: i for i, c in enumerate(alpha)}
    chd = [[-1] * k]
    out = [False]
    for w in banned:
        u = 0
        for ch in w:
            ci = pos[ch]
            v = chd[u][ci]
            if v == -1:
                v = len(chd)
                chd[u][ci] = v
                chd.append([-1] * k)
                out.append(False)
            u = v
        if w:
            out[u] = True
    N = len(chd)
    fail = [0] * N
    from collections import deque
    q = deque()
    for ci in range(k):
        v = chd[0][ci]
        if v == -1:
            chd[0][ci] = 0
        else:
            q.append(v)
    while q:
        u = q.popleft()
        fu = fail[u]
        for ci in range(k):
            v = chd[u][ci]
            if v == -1:
                chd[u][ci] = chd[fu][ci]
            else:
                fail[v] = chd[fu][ci]
                if out[fail[v]]:
                    out[v] = True
                q.append(v)
    good = [i for i in range(N) if not out[i]]
    idx = {node: i for i, node in enumerate(good)}
    s = len(good)
    if 0 not in idx:
        return 0
    M = [[0] * s for _ in range(s)]
    for u in good:
        row = M[idx[u]]
        for ci in range(k):
            iv = idx.get(chd[u][ci])
            if iv is not None:
                row[iv] += 1

    def mul(A, B):
        C = [[0] * s for _ in range(s)]
        for i in range(s):
            Ai = A[i]
            Ci = C[i]
            for t in range(s):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(s):
                        b = Bt[j]
                        if b:
                            Ci[j] = (Ci[j] + a * b) % MOD
        return C

    def mpow(A, e):
        R = [[0] * s for _ in range(s)]
        for i in range(s):
            R[i][i] = 1
        while e:
            if e & 1:
                R = mul(R, A)
            if e > 1:
                A = mul(A, A)
            e >>= 1
        return R

    return sum(mpow(M, n)[idx[0]]) % MOD
